  if((path.equals("/api/auth/login")||path.equals("/api/auth/admin-login"))&&method.equals("POST")){boolean adminOnly=path.equals("/api/auth/admin-login");Map<String,Object>d=body(x);String e=str(d,"email").toLowerCase(Locale.ROOT),p=str(d,"password");try(Connection c=conn();PreparedStatement q=c.prepareStatement("SELECT id,name,email,password_hash,role FROM users WHERE email=?")){q.setString(1,e);try(ResultSet r=q.executeQuery()){if(!r.next()||!verify(p,r.getString("password_hash"))){json(x,401,Map.of("error","Email or password is incorrect."));return;}String role=r.getString("role");if(adminOnly&&!"ADMIN".equals(role)){json(x,403,Map.of("error","This account does not have administrator access."));return;}String old=cookieId(x);if(old!=null)SESSIONS.remove(old);String id=random(32),csrf=random(32);Session session=new Session(csrf,r.getLong("id"),r.getString("name"),r.getString("email"),role,System.currentTimeMillis()+28800000);SESSIONS.put(id,session);setCookie(x,id);json(x,200,Map.of("user",user(session),"redirect",session.role.equals("ADMIN")?"/admin.html":"/dashboard.html","csrf",csrf));}}return;}
  if(path.equals("/api/auth/logout")&&method.equals("POST")){String id=cookieId(x);if(id!=null)SESSIONS.remove(id);x.getResponseHeaders().add("Set-Cookie",COOKIE+"=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax");json(x,200,Map.of("message","Signed out."));return;}
